166|  const minutes = Math.floor((total % 3600) / 60);
167|  const seconds = total % 60;
168|  if (days) return `${days}d ${hours}h ${minutes}m left`;
169|  if (hours) return `${hours}h ${String(minutes).padStart(2, '0')}m ${String(seconds).padStart(2, '0')}s left`;
170|  return `${minutes}m ${String(seconds).padStart(2, '0')}s left`;
