320|function budgetState(person, draftTotal, orderId) {
321|  const cap = Number(session && session.budget_cap);
322|  if (!Number.isFinite(cap) || cap <= 0 || draftTotal == null) return null;
323|  const previous = submittedTotal(person, null);
324|  const candidate = submittedTotal(person, orderId) + draftTotal;
325|  const grandfathered = Boolean(orderId) && candidate > cap + 0.0001
326|    && candidate <= previous + 0.0001;
327|  return {
328|    cap, previous, candidate, grandfathered,
329|    blocked: candidate > cap + 0.0001 && !grandfathered,
330|  };
