633|function payloadEstimate(item, payload) {
634|  let price = Number(item.price || 0);
635|  const unmatchedToppings = (payload.toppings || []).slice();
636|  item.option_groups.forEach((group) => {
637|    let values = [];
638|    if (group.axis === 'toppings') {
639|      values = group.options
640|        .filter((option) => unmatchedToppings.includes(option.label))
641|        .map((option) => option.label);
642|      values.forEach((value) => unmatchedToppings.splice(unmatchedToppings.indexOf(value), 1));
643|    } else if (payload[group.axis]) {
644|      values = [payload[group.axis]];
645|    }
646|    values.forEach((value) => {
647|      const option = selectedOption(group, value);
