371|function drawQrMatrix(context, model, left, top, availableSize) {
372|  const quietModules = 4;
373|  const count = model.getModuleCount();
374|  const moduleSize = Math.floor(availableSize / (count + quietModules * 2));
375|  const size = moduleSize * (count + quietModules * 2);
376|  const x = left + Math.floor((availableSize - size) / 2);
377|  const y = top + Math.floor((availableSize - size) / 2);
378|  context.fillStyle = '#ffffff';
379|  context.fillRect(x, y, size, size);
380|  context.fillStyle = '#000000';
381|  for (let row = 0; row < count; row += 1) {
382|    for (let column = 0; column < count; column += 1) {
383|      if (model.isDark(row, column)) {
384|        context.fillRect(
385|          x + (column + quietModules) * moduleSize,
386|          y + (row + quietModules) * moduleSize,
387|          moduleSize,
388|          moduleSize,
389|        );
390|      }
391|    }
392|  }
