395|function centeredLines(context, value, centerX, startY, maxWidth, lineHeight, maxLines) {
396|  const words = String(value || '').split(/\s+/).filter(Boolean);
397|  const lines = [];
398|  words.forEach((word) => {
399|    const current = lines[lines.length - 1] || '';
400|    const candidate = current ? `${current} ${word}` : word;
401|    if (current && context.measureText(candidate).width > maxWidth && lines.length < maxLines) {
